// Julia Drift: a Julia set whose constant c travels around the rim of the
// Mandelbrot set's main cardioid. Along that rim tiny moves of c reshape the
// whole set, so a slow journey keeps reinventing it: spirals, dragons,
// rabbits, dust. `drift` and `kick` arrive integrated, so their sum is the
// journey position.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t, float j) {
  // The palette's own character drifts along the journey too.
  vec3 d = vec3(0.0, 0.33, 0.67) + 0.15 * vec3(sin(j * 0.05), 0.0, cos(j * 0.037));
  return 0.5 + 0.5 * cos(TAU * (t + d));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0);

  // Form sets where c sits against the rim (inside = solid, rim = lace,
  // outside = dust). Near the middle the journey swings it by itself;
  // pushing the control to an end holds the set there.
  float roam = 1.0 - abs(form);
  float edge = form + roam * 0.7 * sin(j * 0.23) * sin(j * 0.071 + 1.0);
  float theta = j * 0.09 + 2.2;
  vec2 c = 0.5 * vec2(cos(theta), sin(theta)) -
    0.25 * vec2(cos(2.0 * theta), sin(2.0 * theta));
  c *= 1.0 + edge * 0.07;

  // Camera: slow spin, breathing zoom, focus that wanders more when deep.
  float zoom = exp(-depth);
  float span = zoom * (1.35 + 0.25 * sin(j * 0.061));
  vec2 focus = (1.0 - zoom) * 0.4 * vec2(sin(j * 0.047), cos(j * 0.059));
  vec2 w = rot(j * 0.04) * p * span * 2.0 + focus;

  vec2 axis = vec2(cos(j * 0.13), sin(j * 0.13));
  float trap = 1e3;
  float n = 0.0;
  float m2 = 0.0;
  for (int i = 0; i < 90; i++) {
    w = vec2(w.x * w.x - w.y * w.y, 2.0 * w.x * w.y) + c;
    m2 = dot(w, w);
    trap = min(trap, abs(dot(w, axis)));
    if (m2 > 64.0) break;
    n += 1.0;
  }

  float hue = colour + j * 0.021;
  vec3 col;
  if (m2 > 64.0) {
    float sn = n - log2(log2(m2)) + 4.0;
    vec3 band = palette(sn * 0.045 + hue, j);
    col = band * band * 1.4 * (1.0 - exp(-sn * 0.05));
  } else {
    col = palette(hue + 0.5 + trap, j) * 0.08;
  }
  // Orbit trap filaments: light that follows the set's inner structure.
  col += palette(hue + 0.3 + trap * 0.6, j) * glow * 0.012 / (trap + 0.012);

  col *= 1.0 - 0.45 * smoothstep(0.3, 1.0, length(p));
  return clamp(col, 0.0, 1.0);
}
